export function leadForm({title='Talk to a specialist',kind='ready',error=''},actions){const f=document.createElement('form');f.style.cssText='width:360px;display:grid;gap:12px';const h=document.createElement('h2');h.textContent=title;const offer=document.createElement('p');offer.textContent='Implementation plan in 2 business days. No sales call required.';const label=document.createElement('label');label.textContent='Work email';const input=document.createElement('input');input.type='email';input.name='email';input.style.width='100%';label.append(input);const status=document.createElement('p');status.setAttribute('role','status');status.textContent=kind==='error'?error:kind==='success'?'Request received':kind==='loading'?'Sending…':'';const button=document.createElement('button');button.textContent='Get my implementation plan';button.disabled=kind==='loading'||kind==='disabled';f.append(h,offer,label,status,button);f.onsubmit=e=>{e.preventDefault();actions.submit(input.value)};return f;}
export const productionActions={submit:email=>fetch('https://leads.example.invalid/collect',{method:'POST',body:JSON.stringify({email})})};
